        type: "paragraph",
        text: "How much does a business website cost in India in 2026? A basic business website can start around ₹10,000–₹30,000, while professionally designed websites can cost ₹25,000–₹80,000+ and advanced business websites can reach ₹1,00,000–₹1,50,000+ depending on scope."
